UPDATE workforce_employees w SET date_of_birth=CASE WHEN pg_input_is_valid(p.details->'personal'->>'dateOfBirth','date') THEN (p.details->'personal'->>'dateOfBirth')::date ELSE NULL END FROM employee_private_profiles p WHERE p.employee_id=w.id AND p.employer_id=w.employer_id AND pg_input_is_valid(p.details->'personal'->>'dateOfBirth','date') AND p.details->'personal'->>'dateOfBirth' ~ '^\d{4}-\d{2}-\d{2}$';
UPDATE workforce_employees w SET hire_date=CASE WHEN pg_input_is_valid(p.details->'employment'->>'hireDate','date') THEN (p.details->'employment'->>'hireDate')::date ELSE NULL END FROM employee_private_profiles p WHERE p.employee_id=w.id AND p.employer_id=w.employer_id AND pg_input_is_valid(p.details->'employment'->>'hireDate','date') AND p.details->'employment'->>'hireDate' ~ '^\d{4}-\d{2}-\d{2}$';
